package com.office.snacks.service;

import com.office.snacks.dto.ApiDtos.*;
import com.office.snacks.dto.TotalRow;
import com.office.snacks.entity.*;
import com.office.snacks.repository.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import java.math.BigDecimal;

@Service
public class SnackTrackerService {
 private static final ZoneId OFFICE_ZONE=ZoneId.of("Asia/Kolkata");
 private final EmployeeRepository employees; private final SnackRepository snacks; private final SnackRecordRepository records;
 public SnackTrackerService(EmployeeRepository e, SnackRepository s, SnackRecordRepository r){employees=e;snacks=s;records=r;}
 public List<EntityResponse> employees(){return employees.findAllByOrderByNameAsc().stream().map(e->new EntityResponse(e.getId(),e.getName(),e.isActive(),e.getCreatedAt(),null)).toList();}
 public EntityResponse employee(Long id){Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));return new EntityResponse(e.getId(),e.getName(),e.isActive(),e.getCreatedAt(),null);}
 public List<EntityResponse> snacks(){return snacks.findAllByOrderByNameAsc().stream().map(s->new EntityResponse(s.getId(),s.getName(),s.isActive(),s.getCreatedAt(),s.getUnitPrice())).toList();}
 @Transactional public EntityResponse saveEmployee(Long id, EntityRequest req){String name=req.name().trim(); if(employees.findByNameIgnoreCase(name).filter(e->!Objects.equals(e.getId(),id)).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Employee name already exists"); Employee e=id==null?new Employee(name,req.active()):employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found")); if(id!=null)e.update(name,req.active()); e=employees.save(e); return new EntityResponse(e.getId(),e.getName(),e.isActive(),e.getCreatedAt(),null);}
 @Transactional public DeleteResponse deleteEmployee(Long id){Employee e=employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Employee not found"));if(records.existsByEmployee_Id(id)){e.update(e.getName(),false);employees.save(e);return new DeleteResponse(false,"Employee has snack history and was deactivated to preserve its records.");}employees.delete(e);return new DeleteResponse(true,"Employee deleted.");}
 @Transactional public EntityResponse saveSnack(Long id, EntityRequest req){String name=req.name().trim(); if(snacks.findAllByOrderByNameAsc().stream().anyMatch(s->s.getName().equalsIgnoreCase(name)&&!Objects.equals(s.getId(),id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Snack name already exists"); Snack s=id==null?new Snack(name,req.active(),req.unitPrice()):snacks.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Snack not found")); if(id!=null)s.update(name,req.active(),req.unitPrice()); s=snacks.save(s);return new EntityResponse(s.getId(),s.getName(),s.isActive(),s.getCreatedAt(),s.getUnitPrice());}
 @Transactional public DeleteResponse deleteSnack(Long id){Snack s=snacks.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Snack not found"));if(records.existsBySnack_Id(id)){s.update(s.getName(),false);snacks.save(s);return new DeleteResponse(false,"Snack has snack history and was deactivated to preserve its records.");}snacks.delete(s);return new DeleteResponse(true,"Snack deleted.");}
 @Transactional public RecordResponse addRecord(RecordRequest req){if(req.quantity()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity must be greater than zero");if(req.breakType()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose Morning or Evening break");Employee e=employees.findById(req.employeeId()).filter(Employee::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active employee not found")); Snack s=snacks.findById(req.snackId()).filter(Snack::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active snack not found")); SnackRecord r=records.save(new SnackRecord(e,s,req.quantity(),req.breakType())); return recordResponse(r);}
 @Transactional public List<RecordResponse> addRecords(BatchRecordRequest req){if(req.breakType()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose Morning or Evening break");Employee e=employees.findById(req.employeeId()).filter(Employee::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active employee not found"));List<RecordResponse> saved=new ArrayList<>();for(SnackQuantity item:req.items()){if(item.quantity()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Every quantity must be greater than zero");Snack s=snacks.findById(item.snackId()).filter(Snack::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active snack not found: "+item.snackId()));saved.add(recordResponse(records.save(new SnackRecord(e,s,item.quantity(),req.breakType()))));}return saved;}
 @Transactional public RecordResponse updateRecord(Long id,RecordRequest req,Long ownerEmployeeId){if(req.quantity()<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity must be greater than zero");SnackRecord record=records.findDetailedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found"));if(ownerEmployeeId!=null&&!record.getEmployee().getId().equals(ownerEmployeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");Employee employee=employees.findById(req.employeeId()).filter(Employee::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active employee not found"));Snack snack=snacks.findById(req.snackId()).filter(Snack::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Active snack not found"));BreakType type=req.unassigned()?null:req.breakType()==null?record.getBreakType():req.breakType();boolean changedSnack=!Objects.equals(record.getSnack().getId(),snack.getId());BigDecimal price=changedSnack?snack.getUnitPrice():record.getUnitPrice();record.updateSelection(employee,snack,req.quantity(),type,price);return recordResponse(records.save(record));}
 @Transactional public void deleteRecord(Long id,Long ownerEmployeeId){SnackRecord record=records.findDetailedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found"));if(ownerEmployeeId!=null&&!record.getEmployee().getId().equals(ownerEmployeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");records.delete(record);}
 public RecordResponse getRecord(Long id){return getRecord(id,null);}
 public RecordResponse getRecord(Long id,Long employeeId){SnackRecord r=records.findDetailedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found"));if(employeeId!=null&&!r.getEmployee().getId().equals(employeeId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");return recordResponse(r);}
 public List<RecordResponse> history(LocalDate date, LocalDate from, LocalDate to, Long employeeId, Long snackId){LocalDate start=date!=null?date:from; LocalDate end=date!=null?date:to; Instant lo=start==null?null:start.atStartOfDay(OFFICE_ZONE).toInstant(); Instant hi=end==null?null:end.plusDays(1).atStartOfDay(OFFICE_ZONE).toInstant(); if(start!=null&&end!=null&&end.isBefore(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be on or after start date"); return records.filtered(lo,hi,employeeId,snackId).stream().map(SnackTrackerService::recordResponse).toList();}
 public DashboardResponse dashboard(LocalDate date){LocalDate day=date==null?LocalDate.now(OFFICE_ZONE):date; Instant lo=day.atStartOfDay(OFFICE_ZONE).toInstant(), hi=day.plusDays(1).atStartOfDay(OFFICE_ZONE).toInstant();List<RecordResponse> rows=history(day,null,null,null,null);return new DashboardResponse(employees.count(),employees.findAll().stream().filter(Employee::isActive).count(),snacks.findAll().stream().filter(Snack::isActive).count(),records.countByTakenAtGreaterThanEqualAndTakenAtLessThan(lo,hi),records.quantityBetween(lo,hi),breakSummary(rows,BreakType.MORNING),breakSummary(rows,BreakType.EVENING),breakSummary(rows,null));}
 public List<TotalRow> employeeTotals(LocalDate from, LocalDate to){return records.employeeTotals(from.atStartOfDay(OFFICE_ZONE).toInstant(),to.plusDays(1).atStartOfDay(OFFICE_ZONE).toInstant());}
 public List<TotalRow> snackTotals(LocalDate from, LocalDate to){return records.snackTotals(from.atStartOfDay(OFFICE_ZONE).toInstant(),to.plusDays(1).atStartOfDay(OFFICE_ZONE).toInstant());}
 public List<TotalRow> employeeTotals(LocalDate from,LocalDate to,BreakType breakType,boolean unassigned){return totals(history(null,from,to,null,null,breakType,unassigned),RecordResponse::employeeId,RecordResponse::employeeName);}
 public List<TotalRow> snackTotals(LocalDate from,LocalDate to,BreakType breakType,boolean unassigned){return totals(history(null,from,to,null,null,breakType,unassigned),RecordResponse::snackId,RecordResponse::snackName);}
 private List<TotalRow> totals(List<RecordResponse> rows,java.util.function.Function<RecordResponse,Long> id,java.util.function.Function<RecordResponse,String> name){Map<Long,List<RecordResponse>> grouped=new LinkedHashMap<>();rows.forEach(row->grouped.computeIfAbsent(id.apply(row),key->new ArrayList<>()).add(row));return grouped.values().stream().map(group->new TotalRow(id.apply(group.get(0)),name.apply(group.get(0)),group.stream().mapToLong(RecordResponse::quantity).sum(),(long)group.size())).sorted(Comparator.comparing(TotalRow::quantity).reversed().thenComparing(TotalRow::name,String.CASE_INSENSITIVE_ORDER)).toList();}
 public List<RecordResponse> history(LocalDate date,LocalDate from,LocalDate to,Long employeeId,Long snackId,BreakType breakType,boolean unassigned){return history(date,from,to,employeeId,snackId).stream().filter(r->unassigned?r.breakType()==null:breakType==null||r.breakType()==breakType).toList();}
 public BreakSummary breakSummary(List<RecordResponse> rows,BreakType breakType){List<RecordResponse> selected=rows.stream().filter(r->breakType==null||r.breakType()==breakType).toList();long quantity=selected.stream().mapToLong(RecordResponse::quantity).sum(),unpriced=selected.stream().filter(r->r.unitPrice()==null).count();BigDecimal amount=selected.stream().filter(r->r.unitPrice()!=null).map(r->r.unitPrice().multiply(BigDecimal.valueOf(r.quantity()))).reduce(BigDecimal.ZERO,BigDecimal::add);long distinct=selected.stream().map(RecordResponse::snackId).distinct().count();return new BreakSummary(distinct,quantity,selected.size(),amount,unpriced);}
 private static RecordResponse recordResponse(SnackRecord r){return new RecordResponse(r.getId(),r.getEmployee().getId(),r.getEmployee().getName(),r.getSnack().getId(),r.getSnack().getName(),r.getQuantity(),r.getTakenAt(),r.getBreakType(),r.getUnitPrice(),r.getAmount());}
}
